def _is_bz2file(fileobj):
    if HAS_BZ2:
        return isinstance(fileobj, bz2.BZ2File)
    else:
        return False


def _is_lzmafile(fileobj):
    if HAS_LZMA:
        return isinstance(fileobj, lzma.LZMAFile)
    else:
        return False


def _is_lzwfile(fileobj):
    if HAS_UNCOMPRESSPY:
        return isinstance(fileobj, uncompresspy.LZWFile)
    else:
        return False


def _normalize_fits_mode(mode):
    """Normalize a Python binary file mode to an ``io.fits`` mode."""
    if mode is None or mode in IO_FITS_MODES:
        return mode

    if not isinstance(mode, str):
        raise ValueError(f"Mode {mode!r} not recognized")
    if TEXT_RE.fullmatch(mode):
        raise ValueError(
            f"Text mode {mode!r} is not supported: FITS files must be opened "
            "in binary mode"
        )

    normalized = mode
    if "+" in normalized:
        normalized = normalized.replace("+", "") + "+"
    try:
        return FILE_MODES[normalized]
    except KeyError:
        raise ValueError(f"Mode {mode!r} not recognized") from None















class _File:
