def _open_filename(self, filename, mode, overwrite):
    """Open a FITS file from a filename string."""
    if mode == "ostream":
        self._overwrite_existing(overwrite, None, True)

    if os.path.exists(self.name):
        with open(self.name, "rb") as f:
            magic = f.read(6)
